def compute(vars):
    revenue_adjustment = vars["v1"]
    financial_instruments_adjustment = vars["v2"]
    income_tax_adjustment = vars["v3"]
    adjusted_retained_earnings = vars["v4"]

    net_adjustment = (
        revenue_adjustment
        + financial_instruments_adjustment
        + income_tax_adjustment
    )

    trace = {
        "revenue_adjustment": revenue_adjustment,
        "financial_instruments_adjustment": financial_instruments_adjustment,
        "income_tax_adjustment": income_tax_adjustment,
        "net_adjustment": net_adjustment,
        "adjusted_retained_earnings": adjusted_retained_earnings,
        "output_meta": {
            "currency": None,
            "scale": None,
            "unit": "percentage",
        },
    }

    if adjusted_retained_earnings == 0:
        return {"value": None, "trace": trace}

    percentage_net_effect = (net_adjustment / adjusted_retained_earnings) * 100
    trace["percentage_net_effect"] = percentage_net_effect

    return {"value": percentage_net_effect, "trace": trace}
